    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_triggered",
      "explanation": "The doctor did not actively discover that the parent's core uncertainty was about fragmented records and conflicting diagnoses; the parent's own narrative revealed this, and the doctor's response remained generic.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": false,
      "triggered": false
    },
    {
      "active_model_action": true,
      "citations": [
        {
